{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "In rhesus monkeys, [18F]MK-1312 and [18F]2b, neutral amide/heteroaromatic tracers with a lactam and fluoropyridine, showed rapid brain penetration and accumulation in gray matter, demonstrating that amide-rich, moderately polar scaffolds can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "JJC 4-077, a large amide with an aromatic tricyclic system and a hydroxypropyl-piperazine side chain, entered the brain quickly and showed high brain penetration after IV administration, indicating that a hydroxyl-containing polar side chain does not preclude CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Netupitant, a high-molecular-weight lipophilic amide with a biphenyl and tertiary amine, crossed the BBB and distributed to cortical and striatal regions in a PET study, supporting that large amide-rich molecules can have meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A benzamide with a basic piperidine showed very low initial brain uptake in mice; however, the query is neutral and lacks the basic piperidine, so this negative result is less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted pass: direct brain-uptake evidence from neutral/lipophilic amide-containing CNS penetrants (PET tracers, netupitant, JJC 4-077) outweighs the unfavorable physicochemical prior and negative results from basic-amine-containing analogues that are structurally less transferable. Confidence is low due to modest similarity and lack of direct query data.",
  "evidence_gaps": [
    "No direct experimental brain/plasma, CSF, or PET data for the query molecule.",
    "All evidence molecules have Morgan similarity <0.23, so transfer is limited.",
    "No direct P-gp/BCRP efflux data for the query or close analogues; efflux liability is inferred.",
    "The query's bis(2-hydroxyethyl)amide and high TPSA are not closely represented in the most transferable analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

